const MovieCard = ({ movie }) => {
  return (
    <div className="card">
      <img src={movie.poster_path} alt={movie.title} style={{ width: "100%" }} />
      <h3>{movie.title}</h3>
      <pre style={{ whiteSpace: "pre-wrap" }}>{movie.description}</pre>
    </div>
  );
};

export default MovieCard;
